'use strict';
/* NUSAJIWA 1.0 · LIVING WORLD — additive upgrade over 0.9. All legacy saves retained. */
const NJ_WORLD_VERSION='1.0';
const NJ_LANTERN_KEY='nusajiwa-lentera-v10';
const NJ_WORLD_BACKGROUNDS={bara:'data:image/jpeg;base64,',kabut:'data:image/jpeg;base64,',rembulan:'data:image/jpeg;base64,',rimba:'data:image/jpeg;base64,'};
const NJ_MAX_RITUALS=3;
let njRitual=null,njRitualRAF=0,njPhotoURL=null;
const njHour=()=>new Date().getHours();
function njMood(){const h=njHour();return h>=20||h<5?'night':h>=17?'dusk':'day';}
function njMoodText(){return {day:'Cahaya Pagi',dusk:'Senja Nusantara',night:'Malam Bintang'}[njMood()];}
function njUpdateMood(){document.body.classList.toggle('nj-day',njMood()==='day');document.body.classList.toggle('nj-dusk',njMood()==='dusk');document.body.classList.toggle('nj-night',njMood()==='night');}
function njCalendarKey(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function njReadLantern(){try{const val=JSON.parse(localStorage.getItem(NJ_LANTERN_KEY)||'null');if(val&&val.date===njCalendarKey())return {date:val.date,runs:Math.min(NJ_MAX_RITUALS,Math.max(0,val.runs|0)),best:Math.max(0,val.best|0),total:Math.max(0,val.total|0)};}catch(_){}return {date:njCalendarKey(),runs:0,best:0,total:0};}
function njWriteLantern(val){try{localStorage.setItem(NJ_LANTERN_KEY,JSON.stringify(val));}catch(_){toast('Penyimpanan perangkat tidak tersedia.');}}
function njWorldLanternIcon(){return `<svg viewBox="0 0 72 80" aria-hidden="true"><defs><radialGradient id="njLanLight"><stop stop-color="#fff5c9"/><stop offset=".33" stop-color="#f6bc66"/><stop offset="1" stop-color="#f7bd4d" stop-opacity="0"/></radialGradient><linearGradient id="njLanMetal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fbe5a5"/><stop offset="1" stop-color="#956a48"/></linearGradient></defs><circle cx="36" cy="39" r="34" fill="url(#njLanLight)" opacity=".8"/><path d="M21 23L36 12L51 23V57L36 69L21 57Z" fill="#133a43b5" stroke="url(#njLanMetal)" stroke-width="3"/><path d="M22 24h29M21 56h30M36 14v53" stroke="#e8ca8e" stroke-width="2" opacity=".8"/><path d="M31 40c0-9 6-11 5-19 9 11 12 16 7 24-5 9-12 8-12-5" fill="#ffe6a0" opacity=".92"/><circle cx="36" cy="44" r="7" fill="#fff4c3"/><path d="M25 30L36 22L47 30" fill="none" stroke="#fcebc1" stroke-width="1.5"/></svg>`;}
function njPhotoIcon(){return '<svg viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3.5" y="8" width="25" height="19" rx="4"/><path d="M10 8l2-4h8l2 4"/><circle cx="16" cy="18" r="6"/><circle cx="16" cy="18" r="2" fill="currentColor" stroke="none"/><path d="M24 12h.1" stroke-width="3"/></svg>'}
function njCanopySVG(){return `<svg viewBox="0 0 130 170" aria-hidden="true"><defs><linearGradient id="njBranch" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#113c3a"/><stop offset="1" stop-color="#05242d"/></linearGradient></defs><path d="M10-4Q80 38 81 164" stroke="#0b262b" stroke-width="6" fill="none"/>${Array.from({length:7},(_,i)=>{const y=i*21+14,x=29+i*7;return `<g opacity="${.68+(i%3)*.08}"><path d="M${x} ${y} Q${x-36} ${y-34} ${x-36} ${y-54} Q${x-2} ${y-41} ${x} ${y}Z" fill="url(#njBranch)"/><path d="M${x} ${y}Q${x+23} ${y-42} ${x+51} ${y-43}Q${x+38} ${y-11} ${x} ${y}Z" fill="#153b38"/></g>`}).join('')}</svg>`}
const njPreviousScenery10=scenery;
scenery=function(key){let html=njPreviousScenery10(key);if(!html.includes('premium-scene'))return html;
 const kind=key==='komodo'||key==='tiger'?'bara':key==='kuyang'?'rembulan':['cendrawasih','maleo','bekantan'].includes(key)?'kabut':'rimba';
 const rain=kind==='kabut';const drops=Array.from({length:rain?24:14},(_,i)=>`<i class="${rain?'nj-rain':'nj-leaf'}" style="--x:${(i*37+11)%100}%;--dur:${rain?(.9+(i%5)*.26):(10+(i%7)*1.6)}s;--delay:-${(i*1.7)%13}s"></i>`).join('');
 const overlay=`<div class="nj-sky-haze"></div><div class="nj-cloud one"></div><div class="nj-cloud two"></div><div class="nj-world-mist"></div><div class="nj-weather">${drops}</div><div class="nj-canopy"><div class="frond left">${njCanopySVG()}</div><div class="frond right">${njCanopySVG()}</div><div class="frond bottom">${njCanopySVG()}</div></div>`;
 const end=html.lastIndexOf('</div>');return html.slice(0,end)+overlay+html.slice(end);
};
const njPreviousHome10=home;
home=function(){let html=njPreviousHome10();if(!current())return html;
 const remains=NJ_MAX_RITUALS-njReadLantern().runs;
 const tools=`<button type="button" class="nj-world-gesture" data-nj="lantern" aria-label="Mainkan ritual Lentera Jiwa. Kesempatan hari ini ${remains} dari ${NJ_MAX_RITUALS}">${njWorldLanternIcon()}<span>Lentera Jiwa<small class="lantern-daily">${remains} ritual hari ini</small></span></button><button class="nj-capture-btn" data-nj="photo" aria-label="Foto sahabat dan habitat">${njPhotoIcon()}</button>`;
 return html.replace('<div class="home-content">',`<div class="nj-scene-hour"><i class="nj-sky-indicator"></i>${njMoodText()}</div>${tools}<div class="home-content">`);
};
const njPrevRender10=render;
render=function(){njUpdateMood();njPrevRender10();};
function njCloseRitual(){if(njRitualRAF)cancelAnimationFrame(njRitualRAF);njRitualRAF=0;njRitual=null;document.getElementById('njRitualRoot')?.remove();document.body.classList.remove('nj-ritual-open');render();}
function njRitualMarkup(){return `<section class="nj-ritual" id="njRitualRoot" role="dialog" aria-modal="true" aria-label="Ritual Lentera Jiwa"><canvas id="njRitualCanvas" aria-label="Ketuk cahaya yang melayang untuk mengumpulkannya"></canvas><header class="nj-ritual-top"><button class="nj-ritual-exit" data-nj="ritual-exit" aria-label="Keluar ritual">×</button><div class="nj-ritual-head"><small>NUSAJIWA · RITUAL ALAM</small><h2>Lentera Jiwa</h2></div><div class="nj-ritual-meter"><strong id="njRitualClock">30</strong><small>detik</small></div></header><div class="nj-ritual-tip" id="njRitualTip">Ketuk kunang-kunang emas ✦<br>Jaga ritmemu, kumpulkan sebanyaknya!</div><footer class="nj-ritual-footer"><span>Cahaya <b class="nj-ritual-score" id="njRitualScore">0</b></span><span class="nj-ritual-streak" id="njRitualCombo">✦ Kombinasi 0</span></footer></section>`}
function njLanternStart(){if(!current())return toast('Pilih telur penjaga terlebih dahulu.');if(njRitual)return;
 const saveData=njReadLantern();if(saveData.runs>=NJ_MAX_RITUALS){toast('Lentera kembali bersinar esok hari.');return;}
 if(modalOpen)closeModal();saveData.runs++;njWriteLantern(saveData);
 document.body.insertAdjacentHTML('beforeend',njRitualMarkup());document.body.classList.add('nj-ritual-open');
 const c=document.getElementById('njRitualCanvas'),g=c.getContext('2d');
 if(!g){njCloseRitual();toast('Perangkat tidak mendukung ritual ini.');return;}
 njRitual={canvas:c,g,worlds:[],stars:Array.from({length:62},(_,i)=>({x:(i*73+17)%101/100,y:(i*41+7)%88/100,r:.4+(i%5)*.23})) ,ripples:[],start:performance.now(),last:performance.now(),lastDraw:0,seconds:30,score:0,streak:0,bestCombo:0,finished:false,points:0,dpr:1};
 njResizeRitual();for(let i=0;i<5;i++)njSpawnWisp(i);
 c.addEventListener('pointerdown',njTapWisp,{passive:false});
 njRitualRAF=requestAnimationFrame(njRitualFrame);
}
function njResizeRitual(){if(!njRitual)return;let c=njRitual.canvas,r=c.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1);njRitual.dpr=dpr;c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);njRitual.width=r.width;njRitual.height=r.height;njRitual.g.setTransform(dpr,0,0,dpr,0,0);}
function njSpawnWisp(i=0){if(!njRitual)return;const w=njRitual.width,h=njRitual.height;njRitual.worlds.push({x:w*(.18+Math.random()*.64),y:h*(.36+Math.random()*.39),rad:17+Math.random()*7,t:Math.random()*Math.PI*2,seed:i,vx:(Math.random()-.5)*28,vy:(Math.random()-.5)*13,life:0});}
function njRitualDraw(now){const R=njRitual;if(!R)return;let g=R.g,w=R.width,h=R.height,t=now/1000;
 g.clearRect(0,0,w,h);
 let sky=g.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#04121f');sky.addColorStop(.52,'#103846');sky.addColorStop(1,'#164e4c');g.fillStyle=sky;g.fillRect(0,0,w,h);
 const moon=g.createRadialGradient(w*.72,h*.23,5,w*.72,h*.23,w*.40);moon.addColorStop(0,'#e5d89b6e');moon.addColorStop(.32,'#d8bc6c12');moon.addColorStop(1,'#96b2b000');g.fillStyle=moon;g.fillRect(0,0,w,h);
 g.beginPath();g.arc(w*.72,h*.23,26,0,Math.PI*2);g.fillStyle='#fff0bdc9';g.fill();
 R.stars.forEach((s,i)=>{const alpha=.35+Math.sin(t*1.2+i)*.18;g.globalAlpha=alpha;g.fillStyle='#f7eac9';g.beginPath();g.arc(s.x*w,s.y*h*.77,s.r,0,Math.PI*2);g.fill()});g.globalAlpha=1;
 for(let layer=0;layer<3;layer++){const y=h*(.60+layer*.115);g.beginPath();g.moveTo(0,h);g.lineTo(0,y);for(let x=0;x<=w+30;x+=21){const p=Math.sin(x*.014+layer*1.9+t*.008)*28+Math.sin(x*.04+layer)*10;g.lineTo(x,y+p);}g.lineTo(w,h);g.closePath();g.fillStyle=['#153b44','#103b3f','#092c33'][layer];g.fill();}
 const brushTree=(x,y,s,flip)=>{g.save();g.translate(x,y);g.scale(s*(flip?-1:1),s);g.strokeStyle='#041b28';g.lineWidth=10;g.lineCap='round';g.beginPath();g.moveTo(0,95);g.quadraticCurveTo(24,-10,2,-116);g.stroke();for(let i=0;i<5;i++){let k=-108+i*36;g.beginPath();g.moveTo(i*2,k);g.quadraticCurveTo(i%2?64:-53,k-30,i%2?83:-78,k-75);g.stroke()}g.restore();};
 brushTree(0,h*.76,1.1,false);brushTree(w,h*.72,1.25,true);
 // ancient stone shrine to anchor the scene, visually separate from clickable wisps
 g.fillStyle='#0b2833';g.beginPath();g.moveTo(w*.13,h*.95);g.lineTo(w*.13,h*.74);g.lineTo(w*.21,h*.70);g.lineTo(w*.29,h*.74);g.lineTo(w*.29,h*.95);g.fill();
 g.fillStyle='#1b4448';g.fillRect(w*.177,h*.79,w*.055,h*.17);g.strokeStyle='#baab73a1';g.lineWidth=1.6;g.strokeRect(w*.177,h*.79,w*.055,h*.17);
 const ground=g.createRadialGradient(w*.5,h*.96,0,w*.5,h*.96,w*.6);ground.addColorStop(0,'#cca87914');ground.addColorStop(1,'#121c3000');g.fillStyle=ground;g.fillRect(0,h*.65,w,h*.35);
 R.ripples=R.ripples.filter(a=>t-a.born<.7);for(const a of R.ripples){let v=(t-a.born)/.7;g.globalAlpha=(1-v)*.7;g.strokeStyle='#fff0b0';g.lineWidth=2;g.beginPath();g.arc(a.x,a.y,5+v*51,0,Math.PI*2);g.stroke()}g.globalAlpha=1;
 for(const a of R.worlds){const x=a.x+Math.sin(t*1.5+a.t)*11,y=a.y+Math.cos(t*1.75+a.t)*8;let radius=a.rad*3.8;let glow=g.createRadialGradient(x,y,0,x,y,radius);glow.addColorStop(0,'#fff8c8dc');glow.addColorStop(.10,'#f9d98bc6');glow.addColorStop(.25,'#efb64e71');glow.addColorStop(1,'#e9a94b00');g.fillStyle=glow;g.fillRect(x-radius,y-radius,2*radius,2*radius);g.fillStyle='#fff4c4';g.beginPath();g.arc(x,y,5.5+Math.sin(t*3+a.t)*1.7,0,Math.PI*2);g.fill();g.lineWidth=1.2;g.strokeStyle='#ffeca997';g.beginPath();g.moveTo(x-9,y);g.lineTo(x+9,y);g.moveTo(x,y-9);g.lineTo(x,y+9);g.stroke();}
}
function njRitualFrame(now){const R=njRitual;if(!R||R.finished)return;
 if(document.hidden){R.start+=now-R.last;R.last=now;njRitualRAF=requestAnimationFrame(njRitualFrame);return;}
 const dt=Math.max(0,Math.min(.06,(now-R.last)/1000));R.last=now;
 R.seconds=Math.max(0,30-(now-R.start)/1000);
 if(R.seconds<=0){njFinishRitual();return;}
 for(const a of R.worlds){a.x+=a.vx*dt;a.y+=a.vy*dt;if(a.x<R.width*.14||a.x>R.width*.88)a.vx*=-1;if(a.y<R.height*.37||a.y>R.height*.83)a.vy*=-1;}
 const fps=document.body.classList.contains('nj-economy')?33:16;
 if(now-R.lastDraw>fps){R.lastDraw=now;njRitualDraw(now);const time=document.getElementById('njRitualClock');if(time)time.textContent=String(Math.ceil(R.seconds));}
 njRitualRAF=requestAnimationFrame(njRitualFrame);
}
function njTapWisp(e){if(!njRitual||njRitual.finished)return;e.preventDefault();const R=njRitual,r=R.canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let idx=-1,dist=1e9;const t=performance.now()/1000;
 R.worlds.forEach((a,i)=>{const xx=a.x+Math.sin(t*1.5+a.t)*11,yy=a.y+Math.cos(t*1.75+a.t)*8,d=Math.hypot(xx-x,yy-y);if(d<Math.max(32,a.rad+18)&&d<dist){idx=i;dist=d;}});
 if(idx>=0){R.worlds.splice(idx,1);R.score++;R.streak++;R.bestCombo=Math.max(R.bestCombo,R.streak);R.points+=10+Math.min(R.streak-1,5)*2;R.ripples.push({x,y,born:t});njSpawnWisp(R.score);document.getElementById('njRitualScore').textContent=String(R.score);document.getElementById('njRitualCombo').textContent='✦ Kombinasi '+R.streak;const tip=document.getElementById('njRitualTip');if(tip&&R.score>=2)tip.style.display='none';if(navigator.vibrate)navigator.vibrate(12);sound(430+Math.min(500,R.streak*70),660+Math.min(500,R.streak*50));}
 else{R.streak=0;R.ripples.push({x,y,born:t});document.getElementById('njRitualCombo').textContent='✦ Temukan cahaya';}
}
function njFinishRitual(){const R=njRitual;if(!R||R.finished)return;R.finished=true;cancelAnimationFrame(njRitualRAF);njRitualRAF=0;
 const earned=R.score>=12?24:R.score>=7?16:R.score>=3?9:3,pet=current();state.pearls+=earned;
 if(pet){pet.stats.happy=cap(pet.stats.happy+Math.min(14,R.score));pet.stats.bond=cap(pet.stats.bond+(R.score>=7?5:2));pet.affinity.light=(pet.affinity.light||0)+Math.min(5,Math.floor(R.score/3));}
 let data=njReadLantern();data.best=Math.max(data.best,R.score);data.total+=R.score;njWriteLantern(data);eventLog('Ritual Lentera Jiwa: '+R.score+' cahaya, '+earned+' Mutiara');save();
 const title=R.score>=12?'Cahaya Penjaga Terbangun':R.score>=7?'Ritual Bersinar':'Cahaya Akan Kembali';
 document.getElementById('njRitualRoot').insertAdjacentHTML('beforeend',`<div class="nj-ritual-done"><div class="nj-done-card"><span class="nj-done-mark">✧</span><div class="chapter-kicker">RITUAL TELAH SELESAI</div><h2>${title}</h2><p>Kamu menemukan <b>${R.score} lentera</b> dengan kombinasi terbaik <b>${R.bestCombo}</b>. Setiap cahaya ikut menjaga kehidupan Suaka.</p><div class="nj-done-reward"><span>✦ ${earned} Mutiara</span><span>♡ Jiwa bahagia</span></div><p>Kesempatan tersisa hari ini: ${NJ_MAX_RITUALS-njReadLantern().runs}</p><button data-nj="ritual-close">Kembali ke Suaka →</button></div></div>`);
}
async function njGetImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Aset gambar gagal dimuat: '+src));img.src=src;});}
function njCoverImage(ctx,img,canvasW,canvasH){const scale=Math.max(canvasW/img.width,canvasH/img.height),dw=img.width*scale,dh=img.height*scale;ctx.drawImage(img,(canvasW-dw)/2,(canvasH-dh)/2,dw,dh);}
function njText(ctx,txt,x,y,maxWidth,font='25px Georgia',align='left'){ctx.font=font;ctx.textAlign=align;ctx.fillStyle='#fff0cd';ctx.fillText(txt,x,y,maxWidth);}
async function njGeneratePhoto(){const pet=current();if(!pet)return toast('Belum ada jiwa yang dijaga.');const block=document.createElement('div');block.className='nj-photoload';block.textContent='Menyusun potret habitat ✦';document.body.appendChild(block);
 try{
 const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1500;const g=canvas.getContext('2d');if(!g)throw Error('Canvas tidak didukung');
 const kind=['komodo','tiger'].includes(pet.species)?'bara':pet.species==='kuyang'?'rembulan':['cendrawasih','maleo','bekantan'].includes(pet.species)?'kabut':'rimba';
 const bg=await njGetImage(NJ_WORLD_BACKGROUNDS[kind]);njCoverImage(g,bg,900,1500);
 const dusk=g.createLinearGradient(0,0,0,1500);dusk.addColorStop(0,'#061421ee');dusk.addColorStop(.24,'#101a2700');dusk.addColorStop(.61,'#0b1a2b00');dusk.addColorStop(1,'#071421ee');g.fillStyle=dusk;g.fillRect(0,0,900,1500);
 const core=g.createRadialGradient(450,690,45,450,690,440);core.addColorStop(0,'#f7d99b40');core.addColorStop(1,'#ffdcab00');g.fillStyle=core;g.fillRect(0,250,900,950);
 if(pet.phase===0){const png=await njGetImage(PREMIUM_EGGS[pet.species]||PREMIUM_EGGS.komodo);g.shadowColor='#000b';g.shadowBlur=42;g.shadowOffsetY=27;g.drawImage(png,185,290,530,720);g.shadowBlur=0;g.shadowOffsetY=0;}
 else{let svg=petSVG(pet).replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" ');const uri='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);const sprite=await njGetImage(uri);g.shadowColor='#00151ad9';g.shadowBlur=28;g.shadowOffsetY=34;g.drawImage(sprite,40,380,820,770);g.shadowBlur=0;g.shadowOffsetY=0;}
 // hand-laid editorial border & in-world caption, not a screenshot of the UI
 g.strokeStyle='#f6d9a686';g.lineWidth=2;g.strokeRect(30,30,840,1440);g.strokeStyle='#f6d9a54d';g.strokeRect(43,43,814,1414);
 g.fillStyle='#eed6a5';g.font='20px Georgia';g.textAlign='center';g.fillText('✦   N U S A J I W A   ✦',450,105);
 njText(g,'THE LIVING LEGENDS',450,137,650,'15px Georgia','center');
 g.beginPath();g.moveTo(280,178);g.lineTo(620,178);g.strokeStyle='#f4d79a91';g.stroke();
 njText(g,displayName(pet),450,1190,790,'61px Georgia','center');
 njText(g,PHASES[pet.phase]+'  •  '+SPECIES[pet.species].origin,450,1244,790,'23px Georgia','center');
 g.beginPath();g.moveTo(320,1300);g.lineTo(580,1300);g.strokeStyle='#f4d79a91';g.stroke();
 njText(g,'DARI SUAKA, SEBUAH KISAH DIMULAI',450,1360,790,'17px Georgia','center');
 njText(g,'NUSAJIWA  ·  '+new Date().toLocaleDateString('id-ID',{day:'2-digit',month:'long',year:'numeric'}),450,1405,790,'16px Georgia','center');
 const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Gagal membuat PNG')),'image/png'));if(njPhotoURL)URL.revokeObjectURL(njPhotoURL);njPhotoURL=URL.createObjectURL(blob);
 block.remove();const safeName=pet.species.replace(/[^a-z0-9_-]/gi,'');
 showModal(`<section class="nj-photo-stage"><div class="chapter-kicker">POTRET SAHABAT</div><h2>Kenangan dari Suaka</h2><p>Potret asli dari habitatmu. Simpan atau bagikan petualangan ini.</p><img src="${njPhotoURL}" alt="Potret ${escapeHTML(displayName(pet))} dengan latar habitat fantasi Nusantara"><div class="nj-photo-actions"><a href="${njPhotoURL}" download="NUSAJIWA_${safeName}_${NJ_WORLD_VERSION}.png">⬇ Simpan PNG</a><button type="button" data-nj="photo-share">Bagikan ✦</button></div><p class="nj-photo-helper">Ukuran 900 × 1500 piksel · progres permainan tetap aman.</p></section>`);
 }catch(err){block.remove();toast('Potret belum berhasil: '+(err?.message||'coba lagi'));console.warn('[NUSAJIWA] photo',err);}
}
async function njSharePhoto(){if(!njPhotoURL)return;try{const blob=await(await fetch(njPhotoURL)).blob(),file=new File([blob],'NUSAJIWA_potret.png',{type:'image/png'});if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'NUSAJIWA — The Living Legends'});else toast('Gunakan tombol Simpan PNG untuk menyimpan potret.');}catch(err){if(err?.name!=='AbortError')toast('Gunakan Simpan PNG untuk membagikan potret.');}}
const njPrevSettings10=settingsModal;
settingsModal=function(){njPrevSettings10();const pane=document.querySelector('.modal-pane');if(!pane)return;
 const note=pane.querySelector('p:last-child');if(note&&note.textContent.includes('0.9'))note.textContent='NUSAJIWA Living World 1.1 · save lokal tersimpan di perangkat ini.';
 pane.insertAdjacentHTML('beforeend',`<div style="margin-top:14px;border-top:1px solid #d9c39466;padding-top:13px"><button class="secondary-button" data-nj="photo" style="width:100%;padding:12px">${njPhotoIcon()} &nbsp; Abadikan sahabat dalam PNG</button><p style="font-size:11px;color:#d1d2b9;margin:8px 0">Habitat berubah bersama waktu. Ritual Lentera Jiwa dapat dimainkan hingga ${NJ_MAX_RITUALS} kali per hari.</p></div>`);
};
// Capture-phase routing keeps the older version's click delegation intact.
document.addEventListener('click',e=>{const el=e.target.closest('[data-nj]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();switch(el.dataset.nj){case 'lantern':njLanternStart();break;case 'ritual-exit':if(njRitual&&!njRitual.finished)njFinishRitual();else njCloseRitual();break;case 'ritual-close':njCloseRitual();break;case 'photo':njGeneratePhoto();break;case 'photo-share':njSharePhoto();break;}},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&njRitual){e.preventDefault();e.stopImmediatePropagation();if(njRitual.finished)njCloseRitual();else njFinishRitual();}},{capture:true});
window.addEventListener('resize',()=>{if(njRitual)njResizeRitual();});
